import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import net.minecraft.client.Minecraft;import net.minecraft.client.model.*;import net.minecraft.client.model.geom.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;
public class ArmorChecks{
 static int count;static void ok(boolean value,String msg){count++;if(!value)throw new AssertionError(msg);}
 static String layout(HumanoidModel<?> model){TreeMap<String,String> parts=new TreeMap<>();model.root.children.forEach((k,v)->parts.put(k,v.marker));return parts.toString();}
 public static void main(String[]a)throws Exception{boolean old=a[0].equals("old");List<String> names=Files.readAllLines(Path.of(a[1]));ok(names.size()==876,"all native extensions tested");Minecraft mc=Minecraft.INSTANCE;LivingEntity living=new LivingEntity();HumanoidModel<?> defaults=new HumanoidModel<>(new ModelPart(List.of(),Map.of()));List<Object> extensions=new ArrayList<>();List<Method> methods=new ArrayList<>();List<HumanoidModel<?>> models=new ArrayList<>();Set<HumanoidModel<?>> distinct=Collections.newSetFromMap(new IdentityHashMap<>());TreeMap<String,String> snapshots=new TreeMap<>();
 for(String name:names){Class<?> c=Class.forName(name);Constructor<?> ctor=c.getDeclaredConstructor();ctor.setAccessible(true);Object e=ctor.newInstance();Method m=c.getDeclaredMethod("getHumanoidArmorModel",LivingEntity.class,ItemStack.class,EquipmentSlot.class,HumanoidModel.class);m.setAccessible(true);living.crouch=true;living.baby=true;defaults.riding=true;HumanoidModel<?> result=(HumanoidModel<?>)m.invoke(e,living,new ItemStack(),EquipmentSlot.CHEST,defaults);ok(result.crouching&&result.young&&result.riding,"native pose flags set");ok(result.root.children.size()==7,"all native vanilla bone slots preserved");distinct.add(result);extensions.add(e);methods.add(m);models.add(result);snapshots.put(name,layout(result));}
 ok(mc.models.bakes==(old?1879:10),"bake count across all 876 items");ok(distinct.size()==(old?876:5),"only identical complete geometries shared");ok(old?mc.models.emfRejected>0:mc.models.emfRejected==0,"original reproduces EMF guard; replacement stays below it");
 living.crouch=false;living.baby=false;defaults.riding=false;int baked=mc.models.bakes;for(int cycle=0;cycle<3;cycle++)for(int i=0;i<extensions.size();i++){HumanoidModel<?> result=(HumanoidModel<?>)methods.get(i).invoke(extensions.get(i),living,new ItemStack(),EquipmentSlot.HEAD,defaults);ok(result==models.get(i),"cached geometry reused across frames");ok(!result.crouching&&!result.young&&!result.riding,"pose resets for next wearer");}ok(mc.models.bakes==baked,"rendering repeats cause no layer baking");
 for(int reload=0;reload<2;reload++){if(reload==0)mc.models.reload();else mc.models=new EntityModelSet();int before=mc.models.bakes;for(int i=0;i<extensions.size();i++){HumanoidModel<?> result=(HumanoidModel<?>)methods.get(i).invoke(extensions.get(i),living,new ItemStack(),EquipmentSlot.FEET,defaults);ok(result!=models.get(i),"resource reload invalidates old model references");ok(layout(result).equals(snapshots.get(names.get(i))),"resource reload preserves all geometry mappings");models.set(i,result);}ok(mc.models.bakes-before==(old?1879:10),"bounded rebuild per reload");if(!old)ok(mc.models.emfRejected==0,"reload stays below EMF threshold");}
 if(!old){Class<?> shared=Class.forName("net.mcreator.selfexpression.client.SharedArmorModels");boolean invalid=false;try{shared.getMethod("get",int.class).invoke(null,5);}catch(InvocationTargetException e){invalid=e.getCause() instanceof IllegalArgumentException;}ok(invalid,"invalid shape fails clearly");}
 Files.writeString(Path.of(a[2]),snapshots.toString());System.out.println((old?"BASELINE":"PATCHED")+"_NATIVE_ARMOR_CHECKS="+count+"; uniqueModels="+distinct.size()+"; initialBakes="+baked);}}
